entries[235569] = { ["name"] = "Hammer der Schöpfung", ["text"] = "25 Meter Reichweite\nSofort\nSchlägt das aktuelle Ziel mit einem Hammer voller heiliger Energie und fügt ihm 474142 körperlichen Schaden zu. Dann strömt heilige Energie aus dem Hammer aus und verursacht 395118 Heiligschaden, der auf alle Ziele innerhalb eines frontalen kegelförmigen Bereichs von 20 Metern aufgeteilt wird. Erzeugt außerdem einen Bereich mit Lichtremanenz.\n\nZiele unter teuflischem Einfluss werden von 'Instabile Seele' betroffen." }
