entries[235656] = { ["name"] = "Anpassung: Bebende Schritte", ["text"] = "Sofort\nDie Beine des Zaubernden lassen den Boden erbeben. Jedes Mal, wenn er sich bewegt, werden nahe Gegner von den Schockwellen seiner Schritte zurückgestoßen." }
entries[235658] = { ["name"] = "Anpassung: Sporen", ["text"] = "Sofort\nDie Haut des Zaubernden ist mit instabilen Sporen verseucht. Stößt alle 5 Sek. eine Reihe von Sporen auf Gegner in der Nähe aus, die beim Auftreffen innerhalb von 0 Metern Naturschaden verursachen." }
entries[235659] = { ["name"] = "Anpassung: Ätzendes Blut", ["text"] = "Sofort\nDer Zaubernde blutet stark und alle 3 Sek. bildet sich eine Pfütze von ätzendem Blut. Spielercharaktere, die darin stehen, erleiden pro Sekunde 850 Naturschaden." }
