entries[235661] = { ["name"] = "Klingensturm", ["text"] = "Kanalisiert (Wirken in 6 sek.) 7 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nFührt sofort einen Wirbelangriff aus, der alle Ziele in der Nähe trifft, sowie innerhalb der nächsten 6 Sek. alle 1 Sek. weitere Wirbelangriffe. Während Ihr von den Effekten von 'Klingensturm' betroffen seid, könnt Ihr Euch bewegen, aber keine anderen Aktionen ausführen." }
entries[235662] = { ["name"] = "Klingensturm", ["text"] = "Sofort\nBenötigt Nahkampfwaffe\nGreift in einem Wirbelwind aus Stahl alle Gegner innerhalb von 8 Metern an und fügt jedem Gegner mit beiden Nahkampfwaffen Waffenschaden zu." }
entries[235663] = { ["name"] = "Teufelswutflamme", ["text"] = "Unbegrenzte Reichweite\nSofort\nMarkiert zwei Spielercharaktere als Ziel eines Teufelswutstrahls. Nach 6 Sek. springt der Zaubernde zum Rand der Plattform und feuert einen Strahl Teufelsenergie auf die markierten Spielercharaktere ab, sodass in deren Richtung ein Teufelsfeuerwall erzeugt wird.\n\nSpielercharaktere, die den Teufelsfeuerwall berühren, erleiden alle 2 Sek. 140 Feuerschaden." }
