entries[235753] = { ["name"] = "Schneidiger Schädelstrahler", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMachtgetränktes Seidengewebe (100), Scharfschützenzielfernrohr (2), Infernoschwefel (20), Gehärtetes Teufelsglas (6)\nStellt schneidige Schädelstrahler her.\nBeute von:\nErsatzteilbehälter\n\nSchneidiger Schädelstrahler\nWird beim Anlegen gebunden\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Feuert ein Geschoss auf Euer aktuelles Ziel ab. (5 Min Abklingzeit)\n45\nBenötigt Ingenieurskunst der Verheerten Inseln\n(1)" }
entries[235754] = { ["name"] = "Derber Schädelstrahler", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSteinbalgleder (200), Scharfschützenzielfernrohr (2), Infernoschwefel (20), Gehärtetes Teufelsglas (6)\nStellt derbe Schädelstrahler her.\nBeute von:\nErsatzteilbehälter\n\nDerber Schädelstrahler\nWird beim Anlegen gebunden\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Feuert ein Geschoss auf Euer aktuelles Ziel ab. (5 Min Abklingzeit)\n45\nBenötigt Ingenieurskunst der Verheerten Inseln\n(1)" }
entries[235755] = { ["name"] = "Kettenschädelstrahler", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSturmschuppe (200), Scharfschützenzielfernrohr (2), Infernoschwefel (20), Gehärtetes Teufelsglas (6)\nStellt Kettenschädelstrahler her.\nBeute von:\nErsatzteilbehälter\n\nKettenschädelstrahler\nWird beim Anlegen gebunden\nKopf Kette\n9 Rüstung\n+5 [Beweglichkeit oder Intelligenz]+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Feuert ein Geschoss auf Euer aktuelles Ziel ab. (5 Min Abklingzeit)\n45\nBenötigt Ingenieurskunst der Verheerten Inseln\n(1)" }
entries[235756] = { ["name"] = "Schwerer Schädelstrahler", ["text"] = "Wirken in 2 sek.\nReagenzien:\nTeufelsschiefer (100), Scharfschützenzielfernrohr (2), Infernoschwefel (20), Gehärtetes Teufelsglas (6)\nStellt schwere Schädelstrahler her.\nBeute von:\nErsatzteilbehälter\n\nSchwerer Schädelstrahler\nWird beim Anlegen gebunden\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Feuert ein Geschoss auf Euer aktuelles Ziel ab. (5 Min Abklingzeit)\n45\nBenötigt Ingenieurskunst der Verheerten Inseln\n(1)" }
