entries[236185] = { ["name"] = "Meisterlicher Gestaltwandler", ["text"] = "Sofort\nEure Fähigkeiten werden abhängig von Eurer aktuellen Gestalt verstärkt und gewähren einen zusätzlichen Effekt.\n\nNicht verwandelte Gestalt\n'Verjüngung' heilt um 30% mehr Gesundheit und lässt Euch nach dem Wechsel in die Bärengestalt sofort 25 Wut erzeugen.\n\nMondkingestalt\n'Zorn', 'Sternenfeuer' und 'Sternensog' verursachen 30% mehr Schaden und lassen Euch nach dem Wechsel in die Bärengestalt sofort 25 Wut erzeugen.\n\nKatzengestalt\n'Zerfetzen', 'Wilder Biss' und 'Zerfleddern' verursachen 60% mehr Schaden und lassen Euch nach dem Wechsel in die Bärengestalt sofort 50 Wut erzeugen, wenn Ihr beim Einsatz 5 Combopunkte habt." }
