entries[236304] = { ["name"] = "Körperloser Schuss", ["text"] = "Sofort\nHauptmann Yathae Mondstreich zielt mit 'Körperloser Schuss' auf ihr Ziel und fügt ihm nach 4 Sek. 553165 Schattenschaden zu.\n\nSpielercharaktere können sich zwischen sie und ihr Ziel begeben, wodurch der verursachte Schaden unter allen abfangenden Spielercharakteren und dem Ziel aufgeteilt wird.\n\nWenn 'Körperloser Schuss' weniger als 6 Spielercharaktere trifft, explodiert er und fügt allen Gegnern 53578 Schattenschaden zu." }
entries[236305] = { ["name"] = "Körperloser Schuss", ["text"] = "300 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nHauptmann Yathae Mondstreich zielt mit 'Körperloser Schuss' auf ihr Ziel und fügt ihm nach 4 Sek. 553165 Schattenschaden zu.\n\nSpielercharaktere können sich zwischen sie und ihr Ziel begeben, wodurch der verursachte Schaden unter allen abfangenden Spielercharakteren und dem Ziel aufgeteilt wird.\n\nWenn 'Körperloser Schuss' weniger als 6 Spielercharaktere trifft, explodiert er und fügt allen Gegnern 53578 Schattenschaden zu." }
